  async function ensure(){if(!state.session||!state.session.refreshToken)throw new Error("AUTH_REQUIRED");if(state.session.idToken&&state.session.expiresAt>Date.now()+120000)return state.session;const d=await request(TOKEN+"?key="+encodeURIComponent(CONFIG.apiKey),{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"grant_type=refresh_token&refresh_token="+encodeURIComponent(state.session.refreshToken)});setAuth({localId:d.user_id,idToken:d.id_token,refreshToken:d.refresh_token,expiresIn:d.expires_in},state.session.email);return state.session}
  async function db(method,path,body){const s=await ensure(),url=String(CONFIG.databaseUrl||"").replace(/\/$/,"")+"/"+String(path).replace(/^\//,"")+".json?auth="+encodeURIComponent(s.idToken),opt={method,headers:{"Content-Type":"application/json"}};if(body!==undefined)opt.body=JSON.stringify(body);return request(url,opt,19000)}
  function friendly(e){const c=String(e&&e.message||e||"");if(c.includes("INVALID_LOGIN_CREDENTIALS")||c.includes("INVALID_PASSWORD"))return"The email or password is incorrect.";if(c.includes("EMAIL_NOT_FOUND"))return"No account was found for that email.";if(c.includes("PERMISSION_DENIED"))return"This account is not permitted to perform that action.";if(c.includes("REQUEST_TIMEOUT"))return"The server took too long to respond.";if(c.includes("EMAIL_EXISTS"))return"An authentication account already uses that email.";return"The operation could not be completed. Please try again."}
