  function owner(){return state.role==="owner"}function can(permission){return owner()||!!(state.staff&&state.staff.active&&state.staff.permissions&&state.staff.permissions[permission])}
  function canAdvanceOrder(o,status){if(!o||!status||status==="Assigned")return false;if(owner())return true;return status==="Handed to rider"?can("handover"):can("orders")}
