  function nav(){const p=parent();return'<nav class="tabs" aria-label="Operations navigation">'+[["dashboard","home","Home"],["orders","orders","Orders"],["restaurants","restaurant","Restaurants"],["riders","riders","Partners"],["more","more","More"]].map(x=>'<button class="nav-button '+(p===x[0]?'active':'')+'" data-action="go" data-route="'+x[0]+'">'+icon(x[1])+'<span>'+x[2]+'</span></button>').join("")+'</nav>'}
