  function screenLogin(){return'<main class="screen no-nav"><div class="content" style="max-width:520px"><div class="stack-lg" style="padding-top:min(10vh,80px)"><div class="cluster">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Secure operations workspace</p></div></div><div><p class="eyebrow">Owner and restaurant staff</p><h1 class="display" style="margin-top:7px">Run every order with clarity.</h1><p class="supporting" style="font-size:15px;margin-top:12px">Sign in with an approved owner or scoped staff account.</p></div>'+banner()+'<form id="login-form" class="card form-grid"><div class="field"><label for="login-email">Work email</label><input id="login-email" class="input" name="email" type="email" inputmode="email" autocomplete="email" required></div><div class="field"><label for="login-password">Password</label><input id="login-password" class="input" name="password" type="password" autocomplete="current-password" required></div><button class="button primary full" type="submit" '+(state.loading?'disabled':'')+'>'+(state.loading?'<span class="spinner"></span> Verifying access…':icon("lock")+' Sign in securely')+'</button><button class="text-button" type="button" data-action="reset-password">Forgot password?</button></form><div class="notice info">'+icon("shield","small")+'<span>Owner access is verified against the authenticated Firebase identity. Staff can see only their assigned restaurant and permitted operations.</span></div></div></div></main>'}
