  async function saveMenuItem(form){if(!owner())return;const r=restaurant(form.dataset.restaurantId),existingId=form.dataset.itemId,fd=new FormData(form);if(!r)return;const name=String(fd.get("name")||"").trim(),category=String(fd.get("category")||"").trim(),price=Number(fd.get("price"));if(!name||!category||!Number.isFinite(price)){toast("Complete name, category and price.","danger");return}const id=existingId||slug(name)+"-"+Math.random().toString(36).slice(2,6),menu=Array.isArray(r.menu)?r.menu.slice():[],index=menu.findIndex(i=>i.id===id),before=index>=0?menu[index]:{},item=Object.assign({},before,{id,name,category,description:String(fd.get("description")||"").trim(),price,diet:String(fd.get("diet")||"veg"),available:fd.get("available")==="on",popular:fd.get("popular")==="on",archived:false,updatedAt:Date.now()});if(state.itemMediaDraft)item.image=state.itemMediaDraft;if(index>=0)menu[index]=item;else menu.push(item);const record=Object.assign({},r,{menu,updatedAt:Date.now()});try{await db("PUT",ROOT+"/catalog/restaurants/"+r.id,record);state.catalog[r.id]=record;state.itemMediaDraft="";closeSheet();await writeAudit(existingId?"menu.update":"menu.create",r.id+"/"+id,name);toast("Menu item saved.","success");render({preserve:true})}catch(e){toast("Menu item save failed. "+friendly(e),"danger")}}
