  function compressImage(file,maxSize,quality){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type)){reject(new Error("Choose a JPEG, PNG or WebP image."));return}if(file.size>12*1024*1024){reject(new Error("Image must be smaller than 12 MB."));return}const reader=new FileReader();reader.onerror=()=>reject(new Error("Image could not be read."));reader.onload=()=>{const imageObj=new Image();imageObj.onerror=()=>reject(new Error("Image could not be decoded."));imageObj.onload=()=>{const max=maxSize||1100,scale=Math.min(1,max/Math.max(imageObj.width,imageObj.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(imageObj.width*scale));canvas.height=Math.max(1,Math.round(imageObj.height*scale));canvas.getContext("2d").drawImage(imageObj,0,0,canvas.width,canvas.height);let data=canvas.toDataURL("image/jpeg",quality||.76);if(data.length>450000)data=canvas.toDataURL("image/jpeg",.58);if(data.length>470000){reject(new Error("Compressed image is still too large. Choose a simpler photo."));return}resolve(data)};imageObj.src=reader.result};reader.readAsDataURL(file)})}
