  function applyTheme(){const theme=localStorage.getItem("savrivo.control.theme")||"dark";document.documentElement.dataset.theme=theme;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==="dark"?"#071426":"#F6F9FD"}
  async function refresh(){if(state.loading)return;state.loading=true;render({preserve:true});try{await sync(true);toast("Live operations refreshed.","success")}catch(_){toast("Refresh failed.","danger")}finally{state.loading=false;render({preserve:true})}}

  async function handleClick(event){const c=event.target.closest("[data-action]");if(!c)return;const a=c.dataset.action;
    if(a==="close-sheet"){if(c.classList.contains("sheet-backdrop")&&event.target.closest("[data-sheet-surface]"))return;closeSheet();return}
    if(a==="go"){go(c.dataset.route);return}if(a==="back"){back();return}if(a==="refresh"){refresh();return}if(a==="reset-password"){setSheet({type:"reset"});return}
    if(a==="open-order"){go("order",{orderId:c.dataset.orderId});return}if(a==="set-status"){setStatus(c.dataset.orderId,c.dataset.status);return}if(a==="assign-rider"){setSheet({type:"assign",orderId:c.dataset.orderId});return}if(a==="confirm-assign"){assignRider(c.dataset.orderId,c.dataset.riderId);return}if(a==="cancel-order"){setSheet({type:"cancel",orderId:c.dataset.orderId});return}
    if(a==="order-filter"){state.orderFilter=c.dataset.value;document.querySelectorAll('[data-action="order-filter"]').forEach(x=>x.classList.toggle("active",x.dataset.value===state.orderFilter));const node=document.getElementById("order-results");if(node)node.innerHTML=ordersMarkup();return}if(a==="clear-order-filter"){state.orderFilter="active";state.query="";render({preserve:true});return}
    if(a==="new-restaurant"){state.mediaDraft="";go("restaurantEditor",{new:true});return}if(a==="edit-restaurant"){state.mediaDraft="";go("restaurantEditor",{restaurantId:c.dataset.restaurantId});return}if(a==="detect-restaurant-location"){if(window.FeastlyAdminNative&&FeastlyAdminNative.requestRestaurantLocation)FeastlyAdminNative.requestRestaurantLocation();else toast("Location detection is available in the installed app.","danger");return}if(a==="publish-starter"){publishStarter();return}if(a==="toggle-restaurant-archive"){archiveRestaurant(c.dataset.restaurantId);return}if(a==="delete-restaurant"){setSheet({type:"deleteRestaurant",restaurantId:c.dataset.restaurantId});return}
    if(a==="new-menu-item"){state.itemMediaDraft="";setSheet({type:"menuItem",restaurantId:c.dataset.restaurantId,itemId:""});return}if(a==="edit-menu-item"){state.itemMediaDraft="";setSheet({type:"menuItem",restaurantId:c.dataset.restaurantId,itemId:c.dataset.itemId});return}if(a==="delete-menu-item"){setSheet({type:"deleteMenu",restaurantId:c.dataset.restaurantId,itemId:c.dataset.itemId});return}if(a==="confirm-delete-menu"){deleteMenuItem(c.dataset.restaurantId,c.dataset.itemId);return}
    if(a==="review-rider"){go("riderReview",{riderId:c.dataset.riderId});return}if(a==="load-rider-docs"){loadRiderDocuments(c.dataset.riderId);return}if(a==="approve-rider"){approveRider(c.dataset.riderId);return}if(a==="reject-rider"){setSheet({type:"rejectRider",riderId:c.dataset.riderId});return}
    if(a==="invite-staff"){setSheet({type:"staff"});return}if(a==="toggle-staff"){toggleStaff(c.dataset.staffId);return}if(a==="new-promotion"){setSheet({type:"promotion",id:""});return}if(a==="edit-promotion"){setSheet({type:"promotion",id:c.dataset.promotionId});return}if(a==="customer-info"){setSheet({type:"customer",userId:c.dataset.userId});return}if(a==="close-ticket"){closeTicket(c.dataset.userId,c.dataset.ticketId);return}
    if(a==="toggle-theme"){localStorage.setItem("savrivo.control.theme",document.documentElement.dataset.theme==="dark"?"light":"dark");applyTheme();render({preserve:true});return}if(a==="confirm-signout"){setSheet({type:"signout"});return}if(a==="signout"){closeSheet();signOut();return}
  }
  app.addEventListener("click",handleClick);sheetRegion.addEventListener("click",handleClick);
  app.addEventListener("input",event=>{if(event.target.id==="order-search"){state.query=event.target.value;const node=document.getElementById("order-results");if(node)node.innerHTML=ordersMarkup()}});
  window.adminLocationReceived=function(lat,lng){const latInput=document.getElementById("restaurant-lat"),lngInput=document.getElementById("restaurant-lng");if(latInput)latInput.value=Number(lat).toFixed(6);if(lngInput)lngInput.value=Number(lng).toFixed(6);toast("Restaurant location pin detected.","success")};window.adminLocationUnavailable=function(){toast("Restaurant location could not be detected. Check permission and Location settings.","danger")};
  document.addEventListener("change",async event=>{if(event.target.id!=="restaurant-image"&&event.target.id!=="item-image")return;const file=event.target.files&&event.target.files[0];if(!file)return;try{const data=await compressImage(file,event.target.id==="restaurant-image"?1200:900,.75),preview=document.getElementById(event.target.id==="restaurant-image"?"restaurant-preview":"item-preview");if(event.target.id==="restaurant-image")state.mediaDraft=data;else state.itemMediaDraft=data;if(preview){preview.src=data;preview.style.display="block"}toast("Image compressed and ready.","success")}catch(e){toast(e.message,"danger")}});

  async function login(form){const email=form.elements.email.value.trim().toLowerCase(),password=form.elements.password.value;if(!/^\S+@\S+\.\S+$/.test(email)||!password){toast("Enter your work email and password.","danger");return}state.loading=true;render({preserve:true});try{const d=await auth("accounts:signInWithPassword",{email,password,returnSecureToken:true});setAuth(d,email);const lookup=await auth("accounts:lookup",{idToken:state.session.idToken}),account=(lookup.users||[])[0];state.session.email=String(account&&account.email||email).toLowerCase();state.session.name=account&&account.displayName||"";if(LEGACY_OWNER_EMAILS.includes(state.session.email)&&!(account&&account.emailVerified===true))throw new Error("OWNER_EMAIL_UNVERIFIED");persistSession();await resolveRole();state.route="dashboard";state.history=[];await sync(true);startPoll();toast("Secure access verified.","success")}catch(e){state.session=null;persistSession();state.role="";toast(String(e.message).includes("STAFF_INACTIVE")?"This staff account is inactive or not approved.":String(e.message).includes("OWNER_EMAIL_UNVERIFIED")?"Verify the owner email before using Savrivo Control.":friendly(e),"danger")}finally{state.loading=false;render()}}
  async function reset(form){const email=form.elements.email.value.trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(email)){toast("Enter a valid email.","danger");return}try{await auth("accounts:sendOobCode",{requestType:"PASSWORD_RESET",email});closeSheet();toast("If the account exists, a reset link was requested.","success")}catch(e){toast(friendly(e),"danger")}}
  document.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(form.id==="login-form")login(form);else if(form.id==="reset-form")reset(form);else if(form.id==="restaurant-form")saveRestaurantForm(form);else if(form.id==="menu-item-form")saveMenuItem(form);else if(form.id==="staff-form")inviteStaff(form);else if(form.id==="promotion-form")savePromotion(form);else if(form.id==="settings-form")saveSettings(form);else if(form.id==="cancel-form")cancelOrder(form.dataset.orderId,form.elements.reason.value);else if(form.id==="delete-restaurant-form")deleteRestaurant(form.dataset.restaurantId,form.elements.confirmation.value);else if(form.id==="reject-rider-form")rejectRider(form.dataset.riderId,form.elements.note.value)});

  async function bootstrap(){applyTheme();if(!state.session){state.route="login";render();app.setAttribute("aria-busy","false");return}state.loading=true;state.route="dashboard";render();try{await ensure();await resolveRole();await sync(true);startPoll()}catch(e){state.session=null;state.role="";persistSession();state.route="login";toast("Your operations session expired. Sign in again.","danger")}finally{state.loading=false;app.setAttribute("aria-busy","false");render()}}
  window.addEventListener("online",()=>{state.online=true;if(state.session)refresh();else render({preserve:true})});window.addEventListener("offline",()=>{state.online=false;render({preserve:true})});document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&state.session&&state.online)sync(true).then(()=>render({preserve:true})).catch(()=>{})});
  bootstrap();
